package tw.xiaoxin.relens;
import android.app.*;import android.content.*;import android.os.*;
public class ConnectionMonitorService extends Service {static final String STATUS="re_connection",ALERT="re_alert";private Handler handler;private final Runnable tick=new Runnable(){public void run(){ReConnectionManager m=ReConnectionManager.get(ConnectionMonitorService.this);getSystemService(NotificationManager.class).notify(40,status("BLE "+m.bleState()+" · P2P "+m.p2pState()));handler.postDelayed(this,15000);}};@Override public void onCreate(){super.onCreate();channels(this);handler=new Handler(Looper.getMainLooper());startForeground(40,status("正在監看連線"));handler.post(tick);AppLog.i("SERVICE","Background connection enabled");}@Override public int onStartCommand(Intent i,int f,int id){return START_STICKY;}@Override public void onDestroy(){handler.removeCallbacks(tick);AppLog.i("SERVICE","Background connection disabled");super.onDestroy();}@Override public android.os.IBinder onBind(Intent i){return null;}private Notification status(String s){return new Notification.Builder(this,STATUS).setSmallIcon(android.R.drawable.stat_sys_data_bluetooth).setContentTitle("RE Lens 背景連線").setContentText(s).setOngoing(true).build();}static void notifyDisconnect(Context c){if(!c.getSharedPreferences("settings",MODE_PRIVATE).getBoolean("disconnect_alert",true))return;channels(c);Notification n=new Notification.Builder(c,ALERT).setSmallIcon(android.R.drawable.stat_notify_error).setContentTitle("HTC RE 已斷線").setContentText("開啟 RE Lens 重新連線").setAutoCancel(true).build();c.getSystemService(NotificationManager.class).notify(41,n);}private static void channels(Context c){if(Build.VERSION.SDK_INT>=26){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel(STATUS,"背景連線",NotificationManager.IMPORTANCE_LOW));n.createNotificationChannel(new NotificationChannel(ALERT,"斷線提醒",NotificationManager.IMPORTANCE_DEFAULT));}}}
